// Generates the suite wiki under .playgentic/wiki/ from step definitions and page
// objects. Run via `npm run wiki`.
//
//   .playgentic/wiki/index.md           GENERATED: entry point linking everything below
//   .playgentic/wiki/steps/<domain>.md  GENERATED: one page per step @domain
//   .playgentic/wiki/pages.md           GENERATED: every page object and its public members
//
//   .playgentic/wiki/CONVENTIONS.md     YOURS: coding style and testing expectations
//   .playgentic/wiki/extensions/*.md    YOURS: per-agent rules for the playgentic agents
//
// Generated files carry a marker on line 1. Re-runs rewrite and prune only marked
// files, so CONVENTIONS.md, extensions/ and anything else you add are never touched.
// The playgentic agents read this folder at runtime, which is why plugin updates
// never overwrite your customisations.

import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join, relative } from "node:path";
import { parseSteps } from "./lib/parse-steps.mjs";
import { parsePages } from "./lib/parse-pages.mjs";

const ROOT = process.cwd();
const WIKI = join(ROOT, ".playgentic", "wiki");
const STEPS_DIR = join(WIKI, "steps");
const MARKER = "<!-- GENERATED by `npm run wiki` — do not edit by hand -->";

const plural = (n, word) => `${n} ${word}${n === 1 ? "" : "s"}`;

function slugify(domain) {
  return (
    domain
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "") || "uncategorized"
  );
}

function groupByDomain(steps) {
  const groups = new Map();
  for (const step of steps) {
    const domain = step.domain || "uncategorized";
    if (!groups.has(domain)) groups.set(domain, []);
    groups.get(domain).push(step);
  }
  return new Map([...groups.entries()].sort(([a], [b]) => a.localeCompare(b)));
}

/** Hand-written files at the wiki root (CONVENTIONS.md, extensions/*.md) to link from the index. */
function userFiles() {
  const isUser = (path) => !readFileSync(path, "utf8").split("\n", 1)[0].includes(MARKER);
  const root = existsSync(WIKI)
    ? readdirSync(WIKI).filter((f) => f.endsWith(".md") && isUser(join(WIKI, f)))
    : [];
  const extDir = join(WIKI, "extensions");
  const ext = existsSync(extDir)
    ? readdirSync(extDir)
        .filter((f) => f.endsWith(".md"))
        .map((f) => `extensions/${f}`)
    : [];
  return [...root.sort(), ...ext.sort()];
}

function renderIndex(groups, pages, stepCount) {
  const own = userFiles();
  const ownRows = own.length ? own.map((f) => `- [${f}](./${f})`).join("\n") : "_none yet_";
  const domainRows = [...groups.entries()]
    .map(
      ([domain, steps]) =>
        `| ${domain} | ${steps.length} | [steps/${slugify(domain)}.md](./steps/${slugify(domain)}.md) |`,
    )
    .join("\n");
  const pageRows = pages
    .map((p) => `| [${p.name}](./pages.md#${p.name.toLowerCase()}) | ${p.summary || "—"} |`)
    .join("\n");

  return `${MARKER}

# Suite wiki

Entry point for humans and coding agents working on this suite. Regenerate with \`npm run wiki\`.

## Read first

These files are yours. They're never regenerated, and the playgentic agents follow them over their own defaults.

${ownRows}

## Steps

**${plural(stepCount, "step")} across ${plural(groups.size, "domain")}.** Reuse these before writing new ones.

| Domain | Steps | Page |
| --- | --- | --- |
${domainRows}

## Page objects

**${plural(pages.length, "page object")}.** See [pages.md](./pages.md) for every public member.

${pages.length ? `| Page object | Summary |\n| --- | --- |\n${pageRows}` : "_No page objects yet. Add them under `tests/pages/`._"}
`;
}

function renderDomain(domain, steps) {
  const sections = steps
    .sort((a, b) => a.pattern.localeCompare(b.pattern))
    .map((step) => {
      const uses = step.uses.length ? step.uses.join(", ") : "none";
      return `### \`${step.keyword}\` ${step.pattern}

${step.description || "_no description_"}

- **Prereq:** ${step.prereq || "none"}
- **Uses:** ${uses}
- **Source:** \`${step.file}:${step.line}\`
`;
    })
    .join("\n");
  return `${MARKER}

# ${domain}

[← back to index](../index.md)

${sections}`;
}

function renderPages(pages) {
  const sections = pages
    .map((p) => {
      const members = p.members.length
        ? p.members
            .map((m) => {
              const sig =
                m.kind === "method"
                  ? `${m.async ? "async " : ""}${m.name}()`
                  : m.kind === "getter"
                    ? `get ${m.name}`
                    : m.name;
              return `- \`${sig}\`${m.summary ? ` — ${m.summary}` : ""}`;
            })
            .join("\n")
        : "_no public members_";
      return `## ${p.name}

${p.summary || "_no description_"}

- **Extends:** ${p.extends ? `\`${p.extends}\`` : "—"}
- **Source:** \`${p.file}:${p.line}\`

${members}
`;
    })
    .join("\n");
  return `${MARKER}

# Page objects

[← back to index](./index.md)

${sections || "_No page objects yet. Add them under `tests/pages/`._\n"}`;
}

/** Remove generated files under `dir` that weren't written this run. */
function prune(dir, keep) {
  if (!existsSync(dir)) return;
  for (const name of readdirSync(dir)) {
    const full = join(dir, name);
    if (!name.endsWith(".md") || keep.has(full)) continue;
    if (readFileSync(full, "utf8").split("\n", 1)[0].includes(MARKER)) rmSync(full);
  }
}

function main() {
  const steps = parseSteps({ root: ROOT });
  const pages = parsePages({ root: ROOT });
  const groups = groupByDomain(steps);
  mkdirSync(STEPS_DIR, { recursive: true });

  const written = new Set();
  const write = (path, content) => {
    writeFileSync(path, content);
    written.add(path);
  };
  for (const [domain, domainSteps] of groups)
    write(join(STEPS_DIR, `${slugify(domain)}.md`), renderDomain(domain, domainSteps));
  write(join(WIKI, "pages.md"), renderPages(pages));
  write(join(WIKI, "index.md"), renderIndex(groups, pages, steps.length));
  prune(STEPS_DIR, written);
  prune(WIKI, written);

  console.log(
    `wiki: ${plural(steps.length, "step")} in ${plural(groups.size, "domain")}, ${plural(pages.length, "page object")} → ${relative(ROOT, WIKI)}/`,
  );
}

main();
